    #[doc = "    \"allowed_channels\": {"]
    #[doc = "      \"description\": \"Non-empty: the artifact's channel of origin must be in this set. An\\nartifact whose origin is unknown fails closed (the predicate exists to\\nprove origin, and an unknown origin proves nothing).\","]
    #[doc = "      \"default\": [],"]
    #[doc = "      \"type\": \"array\","]
    #[doc = "      \"items\": {"]
    #[doc = "        \"type\": \"string\""]
    #[doc = "      }"]
    #[doc = "    },"]
    #[doc = "    \"block_install_scripts\": {"]
    #[doc = "      \"description\": \"Block any package that carries install-time scripts (post-link /\\npre-link / pre-unlink), regardless of what analysis found in them.\","]
    #[doc = "      \"default\": false,"]
    #[doc = "      \"type\": \"boolean\""]
    #[doc = "    },"]
    #[doc = "    \"denied_channels\": {"]
    #[doc = "      \"description\": \"The artifact's channel of origin must not be in this set. An unknown\\norigin matches no entry; restrict origin with `allowed_channels`.\","]
    #[doc = "      \"default\": [],"]
